-- Record where a stage move came from, for the outbox trigger.
create or replace function public.mod_feedback_set_idea_stage(
  _idea uuid,
  _stage text,
  _message text default null,
  _notify boolean default true,
  _origin text default 'user',
  _actor uuid default null
)
returns table (change_id uuid, post_id uuid, notified boolean)
language plpgsql
security definer
set search_path = ''
as $$
declare
  _stage_row public.mod_feedback_idea_stages%rowtype;
  _post record;
  _cid uuid;
  _do_notify boolean;
begin
  if coalesce((select auth.role()), '') <> 'service_role'
     and not public.mod_feedback_is_staff() then
    raise exception 'Staff only' using errcode = '42501';
  end if;
  select * into _stage_row from public.mod_feedback_idea_stages where id = _stage;
  if not found then
    raise exception 'Unknown stage' using errcode = '23503';
  end if;
  perform 1 from public.mod_feedback_ideas where id = _idea for update;
  if not found then
    raise exception 'Unknown idea' using errcode = '23503';
  end if;

  perform set_config('mod_feedback.origin', coalesce(_origin, 'user'), true);
  perform set_config('mod_feedback.stage_cascade', 'on', true);
  update public.mod_feedback_ideas set stage_id = _stage
  where id = _idea and stage_id is distinct from _stage;
  perform set_config('mod_feedback.stage_cascade', 'off', true);

  if _stage_row.portal_status_id is null then
    return;
  end if;
  _do_notify := _notify and _stage_row.notify_voters;
  for _post in
    select p.id from public.mod_feedback_posts p
    where p.idea_id = _idea
      and p.deleted_at is null
      and p.merged_into_id is null
      and p.status_id is distinct from _stage_row.portal_status_id
  loop
    _cid := public.mod_feedback_set_status(
      _post.id, _stage_row.portal_status_id, _message, _do_notify,
      case when _origin = 'user' then 'idea' else _origin end,
      coalesce(_actor, (select auth.uid()))
    );
    if _cid is not null then
      change_id := _cid;
      post_id := _post.id;
      notified := _do_notify;
      return next;
    end if;
  end loop;
end;
$$;

-- Moving an idea enqueues outbound syncs for its linked issues — except to
-- the provider the move came from (loop guard).
create or replace function public.mod_feedback_ideas_enqueue_sync()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  _origin text := coalesce(current_setting('mod_feedback.origin', true), 'user');
begin
  if new.stage_id is null or new.stage_id is not distinct from old.stage_id then
    return new;
  end if;
  insert into public.mod_feedback_sync_outbox (link_id, provider, desired_stage)
  select l.id, l.provider, new.stage_id
  from public.mod_feedback_issue_links l
  join public.mod_feedback_integrations i on i.provider = l.provider
  where l.idea_id = new.id
    and l.sync_enabled
    and i.enabled
    and _origin <> 'provider:' || l.provider;
  return new;
end;
$$;

drop trigger if exists mod_feedback_ideas_enqueue_sync on public.mod_feedback_ideas;
create trigger mod_feedback_ideas_enqueue_sync
  after update of stage_id on public.mod_feedback_ideas
  for each row execute function public.mod_feedback_ideas_enqueue_sync();

-- Adapter modules (feedback-adapter-<tool>) register from their migrations
-- and unregister in their drop.sql.
create or replace function public.mod_feedback_register_provider(
  _provider text,
  _label text,
  _route_base text,
  _capabilities jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'mod_feedback_register_provider: not allowed' using errcode = '42501';
  end if;
  insert into public.mod_feedback_integrations (provider, label, route_base, capabilities)
  values (_provider, _label, _route_base, coalesce(_capabilities, '{}'::jsonb))
  on conflict (provider) do update
    set label = excluded.label,
        route_base = excluded.route_base,
        capabilities = excluded.capabilities;
end;
$$;

create or replace function public.mod_feedback_unregister_provider(_provider text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'mod_feedback_unregister_provider: not allowed' using errcode = '42501';
  end if;
  delete from public.mod_feedback_integrations where provider = _provider;
end;
$$;

-- Every 2 minutes: drain outboxes and poll providers for changed issues.
select public.kit_register_app_schedule(
  'mod-feedback-integrations-sync',
  '*/2 * * * *',
  '/api/mod/feedback/cron/integrations-sync'
);

-- Embeddable module pages (manifest `area: "embed"`, mounted at /embed/<slug>).
--
-- Which outside sites may frame a module's embed pages. proxy.ts reads this
-- (anon key, cached) and answers /embed/<slug>/… with
-- `Content-Security-Policy: frame-ancestors 'self' <origins>`; no rows means
-- only the app itself may frame them. Modules write their list from their
-- own /admin settings through kit_set_embed_origins (service role only).
-- Origins are public by nature (the browser enforces them), so anyone reads.

create table if not exists public.kit_embed_origins (
  module text not null check (module ~ '^[a-z][a-z0-9-]{1,30}$'),
  origin text not null check (
    origin ~ '^https://[a-z0-9]([a-z0-9.-]*[a-z0-9])?(:[0-9]{1,5})?$'
    or origin ~ '^http://(localhost|127\.0\.0\.1)(:[0-9]{1,5})?$'
  ),
  created_at timestamptz not null default now(),
  primary key (module, origin)
);
alter table public.kit_embed_origins enable row level security;

drop policy if exists "kit_embed_origins: read" on public.kit_embed_origins;
create policy "kit_embed_origins: read"
  on public.kit_embed_origins for select to anon, authenticated
  using (true);

-- Replace a module's whole list atomically. Invalid origins raise (the
-- check constraint), so callers validate first.
create or replace function public.kit_set_embed_origins(_module text, _origins text[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select auth.role()), '') in ('authenticated', 'anon') then
    raise exception 'service role only' using errcode = '42501';
  end if;
  delete from public.kit_embed_origins
  where module = _module and not (origin = any (coalesce(_origins, '{}')));
  insert into public.kit_embed_origins (module, origin)
  select _module, o from unnest(coalesce(_origins, '{}')) as o
  on conflict do nothing;
end;
$$;

revoke execute on function public.kit_set_embed_origins(text, text[]) from public, anon, authenticated;
grant execute on function public.kit_set_embed_origins(text, text[]) to service_role;

-- Feedback module · staff digest email.
--
-- A daily cron (the route sends weekly digests on Mondays only) emails staff
-- a summary built from mod_feedback_insights plus the inbox queues. Each
-- staff member can opt out; a run row is claimed before sending so a cron
-- retry never sends the same digest twice.

create table if not exists public.mod_feedback_staff_prefs (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  digest boolean not null default true,
  updated_at timestamptz not null default now()
);
alter table public.mod_feedback_staff_prefs enable row level security;

drop policy if exists "mod_feedback_staff_prefs: own, staff" on public.mod_feedback_staff_prefs;
create policy "mod_feedback_staff_prefs: own, staff"
  on public.mod_feedback_staff_prefs for all to authenticated
  using (user_id = (select auth.uid()) and (select public.mod_feedback_is_staff()))
  with check (user_id = (select auth.uid()) and (select public.mod_feedback_is_staff()));

-- One row per sent digest period (e.g. "daily:2026-11-27", "weekly:2026-11-23").
-- Server-only: RLS on, no policies.
create table if not exists public.mod_feedback_digest_runs (
  period_key text primary key,
  recipients integer not null default 0,
  sent_at timestamptz not null default now()
);
alter table public.mod_feedback_digest_runs enable row level security;

select public.kit_register_app_schedule(
  'mod-feedback-digest',
  '17 14 * * *',
  '/api/mod/feedback/cron/digest'
);
